import Foundation
import Security

/// Two self-signed RSA-2048 certificates for 127.0.0.1 with their keys (PKCS#12, password "test"), made once with openssl and valid for 100 years.
/// They exist only to test certificate pinning. Neither protects anything.
enum TestCertificates {
    struct Pair {
        let p12: Data
        let fingerprint: String
        func identity() throws -> SecIdentity {
            var items: CFArray?
            let status = SecPKCS12Import(p12 as CFData, [kSecImportExportPassphrase as String: "test"] as CFDictionary, &items)
            guard status == errSecSuccess, let first = (items as? [[String: Any]])?.first, let identity = first[kSecImportItemIdentity as String] else {
                throw NSError(domain: NSOSStatusErrorDomain, code: Int(status))
            }
            return identity as! SecIdentity
        }
    }

    static let A = Pair(p12: Data(base64Encoded: "")!, fingerprint: "c6c61c2126fb2b01e1b7474be2e9de325a8bf2bd7c9fa1f26a4770e3c7ec0b2f")
    static let B = Pair(p12: Data(base64Encoded: "")!, fingerprint: "594d80ecbe0b528e3171b924a8d13bbf54c443d9ce9712dc179c94aeb5559a5e")
}
